clear all
close all
clc

% NOTE:
%   This file should be generated by running Main.m.
%   Please replace 'your_file.mat' with the actual output file name
%   produced by Main.m before running this script.

loadFile = 'your_file.mat';
load(loadFile)
close all

% NOTE:
%   This file should be generated by running save_all_files.m after running Main.m
load("all_results_data.mat")

% ---------- Plot ----------
figure
hold on

legLabels = {'First_data', 'Second_data','etc'};
hLines = [];      

for ii = 1:1
    idx = ii;
    
    % (1) subplot 1
    subplot(1,2,1)
    hold on
    h1 = plot(pars.tlist, all_data(idx).c0, 'LineWidth', 1.5);
    xlabel('$t$', 'Interpreter', 'latex', 'FontSize', 16)
    ylabel('$C^*$', 'Interpreter', 'latex', 'FontSize', 16)
    xlim([tmin tmax])
    %title(sprintf('$\\alpha = %.1e$', pars.alpha), 'Interpreter', 'latex', 'FontSize', 16)

    subplot(1,2,2)
    hold on
    U_int = cumtrapz(pars.tlist(:), all_data(idx).u_omega(:) - all_data(idx).u_star(:), 1);
    h3 = plot(pars.tlist, U_int', 'LineWidth', 1.5);
    xlabel('$t$', 'Interpreter', 'latex', 'FontSize', 16)
    ylabel('$\int_0^t \int_{\Omega} \delta u(x,s)\, dx\, ds$', 'Interpreter', 'latex', 'FontSize', 16)
    xlim([tmin tmax])

    hLines = [hLines; h1];  

end
lgd = legend(hLines, legLabels, ...
    'Interpreter', 'latex', ...
    'FontSize', 14, ...
    'Orientation', 'vertical', ... 
    'Box', 'off');
set(lgd, 'Units', 'normalized', 'Position', [0.88, 0.35, 0.1, 0.3]);















